typedef struct{
 uint32_t n,k,directions[256][32],*words[2],*pressure;
 float *x,*growth,*pm,*weights,*g;
 fragment_map_t*maps;asian_genuine_route_t*routes;
 asian_genuine_state_t*state,*initial,*repeat_states;
 ordered_d1_diag_context_t*producer;
 asian_genuine_strip_context_t*strip;
 asian_genuine_strip_output_t*output;
 asian_geometric_cv_context_t*single_ar,*single_cv,*old;
 VSLStreamStatePtr base,work;
 float step_drift,step_diffusion,strikes[32];
 double max_price_reference_error,max_same_state_delta_error;
}fixture_t;

static fixture_t b;static volatile double sink;static int mkl_status;
static uint64_t med_ticks[N_COUNT][K_COUNT][2][CANDIDATES];
static uint64_t med_wall[N_COUNT][K_COUNT][2][CANDIDATES];

static void*a64(size_t bytes){void*p=0;if(posix_memalign(&p,64,bytes))return 0;memset(p,0,bytes);return p;}
static uint32_t sobol(uint32_t index,const uint32_t*v){uint32_t g=index^(index>>1),w=0;for(uint32_t bit=0;g;++bit,g>>=1)if(g&1)w^=v[bit];return w;}
static uint64_t tsc0(void){_mm_lfence();return __rdtsc();}
static uint64_t tsc1(void){unsigned aux;uint64_t t=__rdtscp(&aux);_mm_lfence();return t;}
static uint64_t wall_ns(void){struct timespec t;if(clock_gettime(CLOCK_MONOTONIC_RAW,&t))abort();return(uint64_t)t.tv_sec*UINT64_C(1000000000)+t.tv_nsec;}
static int u64cmp(const void*a,const void*c){uint64_t x=*(const uint64_t*)a,y=*(const uint64_t*)c;return(x>y)-(x<y);}
static uint64_t quantile(const uint64_t*x,uint32_t rank){uint64_t copy[SAMPLES];memcpy(copy,x,sizeof copy);qsort(copy,SAMPLES,8,u64cmp);return copy[rank];}
static uint64_t random_step(uint64_t*x){*x^=*x<<13;*x^=*x>>7;return *x^=*x<<17;}
static void shuffle(uint32_t*x,uint64_t*seed){for(uint32_t i=0;i<CANDIDATES;++i)x[i]=i;for(uint32_t i=CANDIDATES-1;i;--i){uint32_t j=random_step(seed)%(i+1),q=x[i];x[i]=x[j];x[j]=q;}}

static int load_directions(void){FILE*f=fopen("direction_numbers/joe_kuo_6_21201.bin","rb");if(!f)return-1;for(uint32_t d=0;d<256;++d){uint32_t n;if(fread(&n,4,1,f)!=1||n!=32||fread(b.directions[d],4,32,f)!=32){fclose(f);return-1;}}fclose(f);return 0;}
static void produce_ours(void){ordered_d1_x_only_diag(256,b.producer,b.x);asian_vector_exp_range_reduced_array_diag(b.x,b.growth);asian_vector_exp_range_reduced_array_diag(b.x+PATHS,b.growth+PATHS);}

static int prepare_mkl(void){size_t count=3+(size_t)b.n*32;MKL_UINT*p=calloc(count,sizeof*p);if(!p)return-1;p[0]=b.n;p[1]=VSL_USER_QRNG_INITIAL_VALUES;p[2]=VSL_USER_DIRECTION_NUMBERS;for(uint32_t d=0;d<b.n;++d)for(uint32_t k=0;k<32;++k)p[3+d*32+k]=b.directions[d][k];int e=vslNewStreamEx(&b.base,VSL_BRNG_SOBOL,count,p);free(p);if(e||vslSkipAheadStream(b.base,(long long)(8192-1)*b.n)||vslCopyStream(&b.work,b.base))return-1;VSLStreamStatePtr check=0;if(vslCopyStream(&check,b.base))return-1;uint32_t*raw=a64((size_t)b.n*PATHS*4);if(!raw)return-1;e=viRngUniformBits(VSL_RNG_METHOD_UNIFORMBITS_STD,check,b.n*PATHS,raw);for(uint32_t path=0;!e&&path<PATHS;++path)for(uint32_t d=0;d<b.n;++d)if(raw[(size_t)path*b.n+d]!=sobol(8192+path,b.directions[d]))e=-1;free(raw);vslDeleteStream(&check);return e;}

static void release_fixture(void){if(b.work)vslDeleteStream(&b.work);if(b.base)vslDeleteStream(&b.base);free(b.old);free(b.single_cv);free(b.single_ar);free(b.output);free(b.strip);free(b.producer);free(b.repeat_states);free(b.initial);free(b.state);free(b.routes);free(b.maps);free(b.g);free(b.weights);free(b.pm);free(b.growth);free(b.x);free(b.pressure);free(b.words[1]);free(b.words[0]);memset(&b,0,sizeof b);}

static int prepare_fixture(uint32_t n,uint32_t strike_count){memset(&b,0,sizeof b);b.n=n;b.k=strike_count;if(load_directions())return-1;const double dt=1.0/n;b.step_drift=(float)((.03-.5*.20*.20)*dt);b.step_diffusion=(float)(.20*sqrt(dt));b.words[0]=a64(16384);b.words[1]=a64(16384);b.x=a64(32768);b.growth=a64(32768);b.pm=a64((size_t)n*16384);b.weights=a64(n*4);b.g=a64(16384);b.maps=a64(n*sizeof*b.maps);b.routes=a64(n*sizeof*b.routes);b.state=a64(sizeof*b.state);b.initial=a64(sizeof*b.initial);b.repeat_states=a64(32*sizeof*b.repeat_states);b.producer=a64(sizeof*b.producer);b.strip=a64(sizeof*b.strip);b.output=a64(sizeof*b.output);b.single_ar=a64(sizeof*b.single_ar);b.single_cv=a64(sizeof*b.single_cv);b.old=a64(32*sizeof*b.old);b.pressure=a64(32768);if(!b.words[0]||!b.words[1]||!b.x||!b.growth||!b.pm||!b.weights||!b.g||!b.maps||!b.routes||!b.state||!b.initial||!b.repeat_states||!b.producer||!b.strip||!b.output||!b.single_ar||!b.single_cv||!b.old||!b.pressure)return-1;for(uint32_t i=0;i<8192;++i)b.pressure[i]=i;for(uint32_t i=0;i<PATHS;++i){b.words[0][i]=sobol(8192+i,b.directions[0]);b.words[1][i]=sobol(12288+i,b.directions[0]);b.initial->s[i]=100;for(uint32_t k=0;k<32;++k)b.repeat_states[k].s[i]=100;}if(ordered_d1_diag_prepare(b.producer,b.step_drift,b.step_diffusion,8192,ORDERED_D1_DIAG_PREPARE_X3,n))return-1;produce_ours();const uint32_t*sw[2]={b.words[0],b.words[1]};const float*xb[2]={b.x,b.x+PATHS},*gb[2]={b.growth,b.growth+PATHS};uint32_t*target=a64(16384);if(!target)return-1;for(uint32_t k=0;k<n;++k){for(uint32_t i=0;i<PATHS;++i)target[i]=sobol(8192+i,b.directions[k]);if(asian_genuine_prepare_route(sw,2,xb,gb,target,k,n,&b.maps[k],&b.routes[k])){free(target);return-1;}memcpy(&b.weights[k],&b.routes[k].weight_bits,4);}free(target);if(asian_genuine_strip_fixed_strikes(strike_count,b.strikes)||asian_genuine_strip_prepare(b.strip,100,.03,0,.20,1,n,0,0,0,b.strikes,strike_count))return-1;for(uint32_t k=0;k<strike_count;++k){int put=!(b.strip->strikes[k].flags&ASIAN_GENUINE_STRIP_DIRECT_CALL);if(asian_geometric_cv_prepare(&b.old[k],100,b.strikes[k],.03,0,.20,1,n,0,0,0,put))return-1;}if(asian_geometric_cv_prepare(b.single_ar,100,100,.03,0,.20,1,n,0,0,0,ASIAN_GEOMETRIC_CALL)||asian_geometric_cv_prepare(b.single_cv,100,100,.03,0,.20,1,n,0,0,0,ASIAN_GEOMETRIC_CALL)||prepare_mkl())return-1;return 0;}

static void reset_candidate(uint32_t c){memcpy(b.state,b.initial,sizeof*b.state);for(uint32_t k=0;k<b.k;++k)memcpy(&b.repeat_states[k],b.initial,sizeof*b.initial);memset(b.output,0,sizeof*b.output);memset(b.x,0,32768);memset(b.growth,0,32768);memset(b.g,0,16384);if(c>=12){if(vslCopyStreamState(b.work,b.base))abort();memset(b.pm,0,(size_t)b.n*16384);}mkl_status=0;}
static double output_sum(int delta){double x=0;for(uint32_t k=0;k<b.k;++k){x+=b.output->values[k].call_price+b.output->values[k].put_price;if(delta)x+=b.output->values[k].call_delta+b.output->values[k].put_delta;}return x;}

static double run_candidate(uint32_t c){double z=0;switch(c){case 0:produce_ours();asian_genuine_sql_dual_control_diag(b.routes,b.n,b.state);return asian_arithmetic_payoff_reduce_diag(b.state->q,b.single_ar);case 1:produce_ours();asian_genuine_sql_dual_control_diag(b.routes,b.n,b.state);return asian_geometric_cv_payoff_reduce_diag(b.state->q,b.state->l,b.single_cv);case 2:for(uint32_t k=0;k<b.k;++k){produce_ours();asian_genuine_sql_dual_control_diag(b.routes,b.n,&b.repeat_states[k]);z+=asian_arithmetic_payoff_reduce_diag(b.repeat_states[k].q,&b.old[k]);}return z;case 3:for(uint32_t k=0;k<b.k;++k){produce_ours();asian_genuine_sql_dual_control_diag(b.routes,b.n,&b.repeat_states[k]);z+=asian_geometric_cv_payoff_reduce_diag(b.repeat_states[k].q,b.repeat_states[k].l,&b.old[k]);}return z;default:break;}const int mkl=c>=12,delta=(c>=8&&c<=11)||c>=16,cv=(c>=6&&c<=7)||(c>=10&&c<=11)||(c>=14&&c<=15)||c>=18;const uint32_t tile=(c&1)?8:4;if(mkl){mkl_status=vsRngGaussian(VSL_RNG_METHOD_GAUSSIAN_ICDF,b.work,b.n*PATHS,b.pm,b.step_drift,b.step_diffusion);asian_intel_point_major_sql_diag(b.pm,b.n,b.weights,b.state);}else{produce_ours();asian_genuine_sql_dual_control_diag(b.routes,b.n,b.state);}asian_genuine_strip_l_to_g_diag(b.state->l,b.strip,b.g);if(delta){if(asian_genuine_strip_price_delta_diag(b.state->q,b.g,b.strip,cv,tile,b.output))abort();}else if(asian_genuine_strip_price_diag(b.state->q,b.g,b.strip,cv,tile,b.output))abort();return output_sum(delta);}

static void condition(uint32_t c,int pressure_mode){uint64_t sum=1;if(pressure_mode){for(uint32_t i=0;i<8192;++i){b.pressure[i]+=i+3;sum+=b.pressure[i];}}else{const unsigned char*parts[]={ (unsigned char*)b.x,(unsigned char*)b.growth,(unsigned char*)b.routes,(unsigned char*)b.maps,(unsigned char*)b.state,(unsigned char*)b.producer,(unsigned char*)b.strip,(unsigned char*)b.output,(unsigned char*)b.pm};const size_t sizes[]={32768,32768,b.n*sizeof*b.routes,b.n*sizeof*b.maps,sizeof*b.state,sizeof*b.producer,sizeof*b.strip,sizeof*b.output,(size_t)b.n*16384};for(uint32_t part=0;part<(c>=12?9:8);++part)for(size_t i=0;i<sizes[part];i+=64)sum+=parts[part][i];}sink+=sum;}
static void checksum(double value){double sum=value;for(uint32_t i=0;i<PATHS;++i)sum+=b.state->s[i]+b.state->q[i]+b.state->l[i]+b.g[i];for(uint32_t k=0;k<b.k;++k)sum+=b.output->values[k].call_price+b.output->values[k].put_price+b.output->values[k].call_delta+b.output->values[k].put_delta;sink+=sum;}

static void scalar_same_state(int cv,int delta,asian_genuine_strip_output_t*out){for(uint32_t k=0;k<b.k;++k){const asian_genuine_strip_strike_t*r=&b.strip->strikes[k];double p=0,d=0;for(uint32_t i=0;i<PATHS;++i){const float a=(b.strip->initial_q+b.state->q[i])*b.strip->inv_total;const float g=b.g[i];const double ap=fmax(r->direct_sign*((double)a-r->strike),0)*b.strip->discount;const double gp=fmax(r->direct_sign*((double)g-r->strike),0)*b.strip->discount;p+=ap-(cv?gp:0);if(delta){const double da=(double)b.state->q[i]/(b.strip->total_fixings*100.0),dg=(double)b.strip->future_fixings/b.strip->total_fixings*g/100.0;const double ad=r->direct_sign*((double)a-r->strike)>0?r->direct_sign*da*b.strip->discount:0;const double gd=r->direct_sign*((double)g-r->strike)>0?r->direct_sign*dg*b.strip->discount:0;d+=ad-(cv?gd:0);}}p=p/PATHS+(cv?r->geometric_price_exact_direct:0);d=d/PATHS+(cv?r->geometric_delta_exact_direct:0);out->values[k]=(asian_genuine_strip_value_t){p+r->call_price_adjust,p+r->put_price_adjust,d+r->call_delta_adjust,d+r->put_delta_adjust};}}

static int validate_fixture(FILE*json,int*comma){produce_ours();memcpy(b.state,b.initial,sizeof*b.state);asian_genuine_sql_dual_control_diag(b.routes,b.n,b.state);asian_genuine_strip_l_to_g_diag(b.state->l,b.strip,b.g);asian_genuine_strip_output_t *ref=a64(sizeof*ref),*price=a64(sizeof*price),*pd=a64(sizeof*pd);if(!ref||!price||!pd)return-1;b.max_price_reference_error=0;b.max_same_state_delta_error=0;for(int cv=0;cv<2;++cv){scalar_same_state(cv,1,ref);if(asian_genuine_strip_price_diag(b.state->q,b.g,b.strip,cv,4,price)||asian_genuine_strip_price_delta_diag(b.state->q,b.g,b.strip,cv,4,pd))return-1;for(uint32_t k=0;k<b.k;++k){const uint32_t flags=b.strip->strikes[k].flags;const char*call_money=flags&ASIAN_GENUINE_STRIP_CALL_ITM?"ITM":flags&ASIAN_GENUINE_STRIP_CALL_OTM?"OTM":"ATM";const char*put_money=flags&ASIAN_GENUINE_STRIP_CALL_ITM?"OTM":flags&ASIAN_GENUINE_STRIP_CALL_OTM?"ITM":"ATM";const double got[4]={pd->values[k].call_price,pd->values[k].put_price,pd->values[k].call_delta,pd->values[k].put_delta};const double expected[4]={ref->values[k].call_price,ref->values[k].put_price,ref->values[k].call_delta,ref->values[k].put_delta};for(uint32_t o=0;o<4;++o){double e=got[o]-expected[o];if(o<2&&fabs(e)>b.max_price_reference_error)b.max_price_reference_error=fabs(e);if(o>=2&&fabs(e)>b.max_same_state_delta_error)b.max_same_state_delta_error=fabs(e);fprintf(json,"%s{\"N\":%u,\"strike_count\":%u,\"strike\":%.9g,\"strike_bits\":\"0x%08"PRIx32"\",\"call_moneyness\":\"%s\",\"put_moneyness\":\"%s\",\"nearest_atm\":%s,\"estimator\":\"%s\",\"output\":\"%s\",\"value\":%.17g,\"same_Q_G_float64_reference\":%.17g,\"signed_error\":%.17g}",(*comma)++?",":"",b.n,b.k,b.strikes[k],b.strip->strikes[k].strike_bits,call_money,put_money,flags&ASIAN_GENUINE_STRIP_NEAREST_ATM?"true":"false",cv?"geometric_cv":"arithmetic",(const char*[]){"call_price","put_price","call_delta","put_delta"}[o],got[o],expected[o],e);if(fabs(e)>1e-4)return-1;}if(price->values[k].call_price!=pd->values[k].call_price||price->values[k].put_price!=pd->values[k].put_price)return-1;}}free(pd);free(price);free(ref);return 0;}

static const char*classification(uint32_t c){return((c>=8&&c<=11)||c>=16)?"KINK_AMBIGUITY_REPORTED_DIAGNOSTIC":"QUALIFIED_PRICE";}
static int pin_first_cpu(void){cpu_set_t allowed,pinned;CPU_ZERO(&allowed);if(sched_getaffinity(0,sizeof allowed,&allowed))return-1;int cpu=0;while(cpu<CPU_SETSIZE&&!CPU_ISSET(cpu,&allowed))++cpu;if(cpu==CPU_SETSIZE)return-1;CPU_ZERO(&pinned);CPU_SET(cpu,&pinned);if(sched_setaffinity(0,sizeof pinned,&pinned))return-1;return cpu;}

